import sys

def count_multiples(X, A, B, allowed_digits):
    def dfs(current_number, index):
        if current_number > B:
            return 0
        count = 0
        if A <= current_number <= B and current_number % X == 0:
            count += 1
        if index < len(allowed_digits):
            for digit in allowed_digits[index:]:
                new_number = current_number * 10 + int(digit)
                count += dfs(new_number, index)
        return count

    allowed_digits = list(map(int, allowed_digits))
    return dfs(0, 0)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    X = int(data[0])
    A = int(data[1])
    B = int(data[2])
    allowed_digits = data[3]

    result = count_multiples(X, A, B, allowed_digits)
    print(result)

if __name__ == "__main__":
